      && verifier.VerifyField(tablePos, 28 /*SIGNATURE_VERIFIED*/, 1 /*bool*/, 1, false)
      && verifier.VerifyField(tablePos, 30 /*ATTRIBUTION*/, 1 /*pnvAttribution*/, 1, false)
      && verifier.VerifyVectorOfData(tablePos, 32 /*PUBLISHER_KEY*/, 1 /*byte*/, false)
      && verifier.VerifyField(tablePos, 34 /*KEY_SOURCE*/, 1 /*pnvKeySource*/, 1, false)
      && verifier.VerifyString(tablePos, 36 /*REASON*/, false)
      && verifier.VerifyVectorOfData(tablePos, 38 /*PNM_BYTES*/, 1 /*byte*/, false)
      && verifier.VerifyTableEnd(tablePos);
  }
}
